&lt;b&gt;&lt;i&gt;Il existe un mot effet intitul&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bond-Dimensionnel.html&quot; title=&quot;Bond dimensionnel&quot;&gt;Bond dimensionnel&lt;/a&gt;&lt;/i&gt; issu d&#39;Art de la Magie&lt;/i&gt;&lt;/b&gt;&lt;/td&gt;&lt;td style=&quot;height:30px&quot;&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
